using System.Net;
using System.Net.Http.Json;
using sv_b171d70b22a846d48d2d4395f73fc14a.Client.Models;

namespace sv_b171d70b22a846d48d2d4395f73fc14a.Client.Services.Http;

public sealed class HttpShipmentService : IShipmentService
{
    private readonly IHttpClientFactory _httpClientFactory;

    public HttpShipmentService(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var client = _httpClientFactory.CreateClient("ShipmentApi");
        var response = await client.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"Shipment '{trackingNumber}' was not found.");
        }

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct)
            ?? throw new InvalidOperationException("Received null shipment from API.");
    }
}

